/// The gallery's example of `DropZone`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_label = args.text("label");
        let arg_min_height = args.number("min_height") as f32;
        let arg_choosable = args.bool("choosable");
        let arg_disabled = args.bool("disabled");
        let arg_fill = args.bool("fill");
        let arg_hint = args.text("hint");
        let arg_no_hint = args.bool("no_hint");
        let arg_quiet = args.bool("quiet");

        let count = State::new(0_usize);
        let (shown, add) = (count.clone(), count);
        {
            let mut it = DropZone::new(
                Text::bound(&shown, |n| format!("{n} files received. Drop more, or press Enter here."))
                    .style(TextStyle::Callout)
                    .foreground(Semantic::InkMuted),
            )
            .on_files(move |files| add.update(|n| *n += files.len()));
            it = it.label(arg_label.clone());
            it = it.min_height(arg_min_height);
            if arg_choosable {
                it = it.choosable();
            }
            it = it.disabled(arg_disabled);
            if arg_fill {
                it = it.fill();
            }
            if !arg_hint.is_empty() {
                it = it.hint(arg_hint.clone());
            }
            if arg_no_hint {
                it = it.no_hint();
            }
            if arg_quiet {
                it = it.quiet();
            }
            it
        }
    })
}

impl ComponentBook for DropZone<AnyView> {
    fn book() -> Meta {
        Meta::new("Actions and inputs/DropZone", render)
            .summary("Dashed area around any content, which takes dropped files.")
            .arg(ArgType::text("label", "Files of the session"))
            .arg(ArgType::number("min_height", 96.0, 0.0, 384.0, 1.0))
            .arg(ArgType::bool("choosable", true))
            .arg(ArgType::bool("disabled", false))
            .arg(ArgType::bool("fill", false))
            .arg(ArgType::text("hint", "").description("Empty leaves it as the component has it."))
            .arg(ArgType::bool("no_hint", false))
            .arg(ArgType::bool("quiet", false))
            .story("Example", Args::new())
            .story("Disabled", Args::new().with("disabled", true))
    }
}
